INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p614062-mgt410', 'stk-a7med.88', 'MGT 410', 'info', '{"desc": "دكتور المير يا عزيزي …\nفي الأخلاق … مافيه زيه في الجامعه كلها … على كبر سنه … الا أنه يحطك على راسه من فوق …\nفي التدريس … صراحه اختباراته وكوزاته جامدة … يعني يبغالك تاكل الكتاب … القريد مادري عنه … بروجيكت مافيه بس فيه تيرم بيبر … حاجه أسهل من البروجيكت …\nاتمنى اني افدتك … 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt410/88707/3", "user": "a7med.88", "ts": 1274667772000, "tid": 88707, "pn": 3}}', 1274667772000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p276241-mgt410', 'stk-user2263', 'MGT 410', 'info', '{"desc": "نصيييييحتكم … سمعت كلام كثير عن د/القحطاني … لكن ماني عارف ما ابغى اظلم الرجال …\n\nاي احد دارس عنده من قبل بنفس المادة او مادة ثانية لا يبخل علينا بانبطاعه عن الدكتور من ناحية القريدات والتعامل والغياب و و و و و كل شي يعرفه … المادة منزلها بالصيف 073 … وللأسف شبه مضطر اني اخذها …\n\nفي انتظار الردود … 🌹 🌹 🌹 🌹 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mgt-410/63873/1", "user": "user2263", "ts": 1214099097000, "tid": 63873, "pn": 1}}', 1214099097000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
